#!/usr/bin/env bash
# Mutant of voice session-start.sh: an UNBOUNDED additionalContext payload.
#
# Negative control for T22: an unbounded voice injection "silently spends
# context on every compaction" -- the real handler bounds its output to a
# pointer, not a copy. This mutant is the failing case for that bound check.
set -eu
cat <<'JSON'
{"hookSpecificOutput": {"hookEventName": "SessionStart", "additionalContext": ""}}
JSON
exit 0
